 function factDetails(){const selected=facts().find(f=>f.id===state.selection?.id);if(!selected)return null;const related=facts().filter(f=>(f.stay_id||f.source_id)===(selected.stay_id||selected.source_id)&&f.date===selected.date),gps=related.filter(f=>f.source==='gps').reduce((n,f)=>n+f.minutes,0),estimated=related.filter(f=>f.source==='estimated').reduce((n,f)=>n+f.minutes,0);return {selected,related,gps,estimated,start:Math.min(...related.map(f=>f.start)),end:Math.max(...related.map(f=>f.end))};}
 function factHTML(){const details=factDetails();if(!details)return '<p>Участок больше не доступен.</p>';const {selected:f,start,end}=details,confirmed=details.related.every(r=>r.confirmed);return `<div class="pf-popover-head"><h3>${f.kind==='road'?'Дорога':'Стоянка'} · факт выезда</h3>${!state.mobile?'<button type="button" class="btn icon ghost" data-pw="selection-clear" aria-label="Закрыть детали факта">×</button>':''}</div><div class="pf-popover-time"><strong>${plannerClock(start)}–${plannerClock(end)}</strong><span>${duration(end-start)}</span></div><div class="pf-sources">${details.related.map(p=>{const appearance=plannerFactAppearance(p);return `<div class="pf-source-row"><i class="pf-source-key pf-key-${appearance.tone}" style="--pf-fact-color:${appearance.color}"></i><span><strong>${appearance.label}</strong><small>${plannerClock(p.start)}–${plannerClock(p.end)}</small></span><b>${duration(p.minutes/60)}</b></div>`;}).join('')}</div><p class="pf-confirmation ${confirmed?'pf-confirmed':''}">${confirmed?'✓ Подтверждено':'◷ Ожидает проверки'}</p>${f.kind==='stop'?`<p class="hint">${f.order_id?'Связано с заданием №'+(record('order',f.order_id)?.number||'—'):'Не привязано к заданию'}</p>`:''}<div class="pf-panel-actions"><button type="button" class="btn block" data-pw="fact-source">${f.stay_id?'Открыть остановку':'Открыть участок в журнале'}</button><button type="button" class="btn text" data-pw="entity" data-kind="trip" data-id="${f.trip_id}">Открыть выезд →</button></div><p class="pf-footnote">GPS относится к выезду. Личное время работы подтверждается отдельно.</p>`;}
