  gesture={cancel};document.addEventListener('pointermove',move,{capture:true,passive:false});document.addEventListener('pointerup',up,true);document.addEventListener('pointercancel',cancel,true);document.addEventListener('keydown',escape,true);window.addEventListener('blur',cancel);frame=requestAnimationFrame(tick);
